S = {'cc': 'BS', 'fam': 'Corporate', 'doc': '# BS 2025: Corporate family\n\nThe Bahamas levies no corporate income tax: the Ministry of Finance\'s consultation paper on the Domestic Minimum Top-up Tax (Aug 2024, opm.gov.bs) says an income tax system would have to be developed "from the ground up" and that smaller businesses stay under the Business Licence Tax. Grade B (an official statement, not a statute). Payments abroad therefore bear no withholding: cited zeros on all four kinds (`Wht.zeroOn`). The DMTT (Pillar Two, in-scope MNE groups with at least EUR 750 million revenue) stays C: the enacted Act (Nov 2024) was not reached; the Bill was read.', 'families': '[wht.family]', 'taxes': [{'oecd': '1200', 'tax': 'Corporate income tax', 'statute': "none: no income tax is levied in The Bahamas (Ministry of Finance, Introduction of a Domestic Minimum Top-up Tax in The Bahamas, Aug 2024: an income tax would have to be built 'from the ground up'; smaller businesses pay the Business Licence Tax)", 'dated': 'Ministry of Finance consultation paper and DMTT Bill 2024 (opm.gov.bs, archived bs/law/Introduction-of-a-Domestic-Minimum-Top-Up-Tax-in-the-Bahamas.*, Domestic-Minimum-Top-Up-Tax-Bill-2024.*); pass 8, 2026-11-21', 'grade': 'B', 'status': 'not levied', 'package': 'P2', 'kernel_parts': ['Absent'], 'unsupported': []}, {'oecd': '1200', 'tax': 'Withholding on payments to non-residents', 'statute': "no income tax is levied in The Bahamas (Ministry of Finance, Introduction of a Domestic Minimum Top-up Tax in The Bahamas, Aug 2024: an income tax would have to be built 'from the ground up'; smaller businesses pay the Business Licence Tax): none withheld", 'dated': 'Ministry of Finance consultation paper and DMTT Bill 2024 (opm.gov.bs, archived bs/law/Introduction-of-a-Domestic-Minimum-Top-Up-Tax-in-the-Bahamas.*, Domestic-Minimum-Top-Up-Tax-Bill-2024.*); pass 8, 2026-11-21', 'grade': 'B', 'status': 'modelled', 'package': 'P2', 'kernel_parts': ['Wht'], 'unsupported': []}, {'oecd': '1200', 'tax': 'Domestic minimum top-up tax (MNE groups with consolidated revenue of at least EUR 750 million)', 'statute': 'Domestic Minimum Top-up Tax Act 2024 (enacted 28/29 Nov 2024; the Act was not read, the Bill of Aug 2024 was)', 'grade': 'C', 'status': 'unsupported', 'package': 'P2', 'kernel_parts': [], 'tried': 'laws.bahamas.gov.bs 403 to scripts; opm.gov.bs Bill 2024 read', 'unsupported': ['the enacted DMTT Act is not held; group revenue is not an input']}], 'unsupported': [['true', 'Domestic minimum top-up tax (in-scope MNE groups only): enacted Act not read (grade C): not computed']], 'lean': 'def wht : Wht :=\n  { name := "Withholding on payments abroad (none levied)",\n    rules := Wht.zeroOn [.dividend, .interest, .royalty, .services] "no income tax is levied in The Bahamas (Ministry of Finance, Introduction of a Domestic Minimum Top-up Tax in The Bahamas, Aug 2024: an income tax would have to be built \'from the ground up\'; smaller businesses pay the Business Licence Tax): none withheld" }', 'guards': ['wht.amount { kind := .dividend, amount := 1000000 } == 0', 'wht.amount { kind := .interest, amount := 1000000 } == 0', 'wht.amount { kind := .royalty, amount := 1000000 } == 0', 'wht.amount { kind := .services, amount := 1000000 } == 0']}
